using System;
using DSExecution.VirtualMachine;

namespace DOrchestration
{
    /// <summary>The three output categories generated by scripts and their execution host.</summary>
    public enum VMOutputKind
    {
        Print,
        Warning,
        Error
    }

    /// <summary>
    /// An immutable, attributed script message. EntityId is absent for team shared
    /// initialization; its other messages identify the exact entity VM that emitted them.
    /// Sequence preserves the scheduler's deterministic total order across both sides.
    /// </summary>
    public readonly struct VMOutputMessage
    {
        public long Sequence { get; }
        public long Tick { get; }
        public int SideId { get; }
        public int? EntityId { get; }
        public VMOutputKind Kind { get; }
        public string Text { get; }
        public string SourceFile { get; }
        public int SourceLine { get; }
        public int SpanStart { get; }
        public int SpanEnd { get; }

        internal VMOutputMessage(long sequence, long tick, int sideId, int? entityId,
            VMOutputKind kind, string text, VMDebugState debug)
        {
            Sequence = sequence;
            Tick = tick;
            SideId = sideId;
            EntityId = entityId;
            Kind = kind;
            Text = text ?? string.Empty;
            SourceFile = debug?.File;
            SourceLine = debug?.Line ?? -1;
            SpanStart = debug?.SpanStart ?? -1;
            SpanEnd = debug?.SpanEnd ?? -1;
        }
    }
}
